                        neighbor = set()
                        firewall = 0
                        idx = len(neighbors) + 1
                        isInfected[i][j] = -idx
                        while q:
                            x, y = q.popleft()
                            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                                nx, ny = x + dx, y + dy
                                if 0 <= nx < m and 0 <= ny < n:
                                    if isInfected[nx][ny] == 1:
                                        q.append((nx, ny))
